(function (global) {

    function loadScript(src) {
      return new Promise(function (resolve, reject) {
        var s = document.createElement("script");
        s.src = src;
        s.onload = resolve;
        s.onerror = reject;
        document.head.appendChild(s);
      });
    }
  
    async function init() {
  
      // Tunggu sampai window benar-benar siap
      if (document.readyState !== "complete") {
        await new Promise(resolve => window.addEventListener("load", resolve));
      }
  
      // Validasi GSAP
      if (!global.gsap) {
        console.error("GSAP belum diload. Load GSAP dulu sebelum myMotion.");
        return;
      }
  
      try {
  
        // Load semua module secara berurutan
        await loadScript("https://cdn.jsdelivr.net/gh/yuzuyyy/splitMotion@master/dist/split-motion.min.js");
  
        await loadScript("https://cdn.jsdelivr.net/gh/yuzuyyy/splitMotion@master/dist/scramble.min.js");
  
        await loadScript("https://cdn.jsdelivr.net/gh/yuzuyyy/splitMotion@master/dist/pixelTwo.min.js");
  
        await loadScript("https://cdn.jsdelivr.net/gh/yuzuyyy/splitMotion@master/dist/marquee.min.js");
  
        global.SplitMotionBundleReady = true;
  
        console.log("✅ SplitMotion Bundle Loaded Successfully");
  
      } catch (err) {
        console.error("❌ Gagal load SplitMotion bundle:", err);
      }
    }
  
    init();
  
  })(window);